#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> wrap(const std::string& text, std::size_t width)
{
    return {text};
}

int main()
{
    for (const auto& line : wrap("The old wizard looks up from his book and smiles at you.", 30)) std::cout << line << '\n';
}
